/**
 * Read a small text artifact through the API
 *
 * Serve a small text artifact directly instead of signing a URL for it.
 *
 * A signed URL makes the browser's success depend on four separate things
 * being right at once: the signature, the expiry, the bucket's CORS policy,
 * and whichever credentials the process holds at the moment of signing. Run
 * 336's transcript failed on one of them for a day and answered
 * ``SignatureDoesNotMatch``, an error that names the signature and says
 * nothing about which of the four it was.
 *
 * None of those four are needed to hand somebody a few kilobytes of text.
 * The request is already authenticated, the tenancy check is the same one
 * the signed-URL route performs, and the read is a single GET the server
 * makes with credentials it is already using successfully to write
 * recordings. So the transcript comes back through the API.
 *
 * Deliberately not the recordings. Those are megabytes of audio that the
 * browser should stream from object storage rather than through a uvicorn
 * worker that is also carrying live calls -- see AGENTS.md on what those
 * processes are. A signed URL is the right shape for a recording and the
 * wrong shape for a transcript, and this is the second one.
 */
export const getTextArtifactApiV1S3TextGet = <ThrowOnError extends boolean = false>(options: Options<GetTextArtifactApiV1S3TextGetData, ThrowOnError>): RequestResult<GetTextArtifactApiV1S3TextGetResponses, GetTextArtifactApiV1S3TextGetErrors, ThrowOnError> => (options.client ?? client).get<GetTextArtifactApiV1S3TextGetResponses, GetTextArtifactApiV1S3TextGetErrors, ThrowOnError>({ url: '/api/v1/s3/text', ...options });

/**
 * Stream a stored artifact through the API
 *
 * Stream a recording, instead of signing a URL the browser fetches.
 *
 * The transcript moved to ``/s3/text`` for four reasons, and run 336 then
 * settled which of them was live: the text came back fine through the API
 * while the recording, on a presigned URL from the same process against the
 * same bucket with the same credentials, still would not play. So the
 * credentials read S3 correctly and it is the *presigning* that produces a
 * signature S3 rejects. Nothing about a recording will fix that.
 *
 * Streamed rather than read into memory like the transcript, because a
 * recording is megabytes and a browser seeking in an ``<audio>`` element asks
 * for byte ranges. Answering "the ten seconds from 4:10" by loading the whole
 * file would be wrong twice over.
 *
 * The cost is honest and worth naming: these bytes now pass through a uvicorn
 * worker, and those workers are the same processes that carry live calls (see
 * the header of ``scripts/start_services_docker.sh``). At this scale that is
 * a fair trade for a recording that plays. If presigning is ever fixed, the
 * recording can go back to a signed URL and this endpoint can go.
 */
export const streamArtifactApiV1S3StreamGet = <ThrowOnError extends boolean = false>(options: Options<StreamArtifactApiV1S3StreamGetData, ThrowOnError>): RequestResult<StreamArtifactApiV1S3StreamGetResponses, StreamArtifactApiV1S3StreamGetErrors, ThrowOnError> => (options.client ?? client).get<StreamArtifactApiV1S3StreamGetResponses, StreamArtifactApiV1S3StreamGetErrors, ThrowOnError>({ url: '/api/v1/s3/stream', ...options });

